(7624754, 1235277, 173844, '<td valign="top">Congratulations on your new lens (girl or boy?), and much pleasure for you.</td>', 'Congratulations on your new lens (girl or boy?), and much pleasure for you.', '2019-04-15 09:34:38.000000', NULL, 0),
(7624755, 1234989, 173844, '<td valign="top">I wish I had taken the time to look at this more sympathetically, for it has a lot of power.</td>', 'I wish I had taken the time to look at this more sympathetically, for it has a lot of power.', '2019-04-15 09:39:02.000000', NULL, 0),
(7624756, 1235032, 173844, '<td valign="top">It often pays to take a long look at the images at the end of the jagged line, and so I have and am rewarded.  I do now see a lovely, subtle, fascinating study.  For me, the rose has transitioned into an eye, and the iris (get it, a flower) is now an evocation of all the magic that exists.</td>', 'It often pays to take a long look at the images at the end of the jagged line, and so I have and am rewarded.  I do now see a lovely, subtle, fascinating study.  For me, the rose has transitioned into an eye, and the iris (get it, a flower) is now an evocation of all the magic that exists.', '2019-04-15 09:47:32.000000', NULL, 0),
(7624758, 1235171, 135744, '<td valign="top">Surprised this didn''t finish higher. Really great moment captured with perfection</td>', 'Surprised this didn''t finish higher. Really great moment captured with perfection', '2019-04-15 10:27:29.000000', NULL, 0),
